"use client";

import { useState, useEffect } from "react";
import { DoctorAppointment, getDoctorAppointments, updateAppointmentStatus, updateAppointmentDetails } from "@/services/doctorService";

/* ─── Status Configs ─── */
const APPOINTMENT_STATUS: Record<string, { label: string; icon: string; text: string; bg: string; border: string; dot: string }> = {
    PENDING: { label: "Chờ xác nhận", icon: "⏳", text: "text-amber-700", bg: "bg-amber-50", border: "border-amber-200", dot: "bg-amber-400" },
    CONFIRMED: { label: "Đã xác nhận", icon: "✅", text: "text-blue-700", bg: "bg-blue-50", border: "border-blue-200", dot: "bg-blue-400" },
    COMPLETED: { label: "Hoàn thành", icon: "🎉", text: "text-green-700", bg: "bg-green-50", border: "border-green-200", dot: "bg-green-400" },
    CANCELLED: { label: "Đã hủy", icon: "❌", text: "text-red-700", bg: "bg-red-50", border: "border-red-200", dot: "bg-red-400" },
    RESCHEDULED: { label: "Đổi lịch", icon: "🔄", text: "text-purple-700", bg: "bg-purple-50", border: "border-purple-200", dot: "bg-purple-400" },
};

const PAYMENT_STATUS: Record<string, { label: string; icon: string; text: string; bg: string }> = {
    PENDING: { label: "Chưa thanh toán", icon: "💳", text: "text-amber-600", bg: "bg-amber-50" },
    PAID: { label: "Đã thanh toán", icon: "✅", text: "text-green-600", bg: "bg-green-50" },
    CANCELLED: { label: "Đã hủy TT", icon: "🚫", text: "text-red-600", bg: "bg-red-50" },
};

const FILTER_TABS = [
    { value: "ALL", label: "Tất cả", icon: "📋" },
    { value: "PENDING", label: "Chờ xác nhận", icon: "⏳" },
    { value: "CONFIRMED", label: "Đã xác nhận", icon: "✅" },
    { value: "COMPLETED", label: "Hoàn thành", icon: "🎉" },
    { value: "CANCELLED", label: "Đã hủy", icon: "❌" },
    { value: "RESCHEDULED", label: "Đổi lịch", icon: "🔄" },
];

/* ─── Helpers ─── */
const formatDate = (d: string) => {
    try {
        return new Date(d).toLocaleDateString("vi-VN", { weekday: "short", day: "2-digit", month: "2-digit", year: "numeric" });
    } catch { return d; }
};

const formatCurrency = (n: number) =>
    new Intl.NumberFormat("vi-VN", { style: "currency", currency: "VND" }).format(n);

const timeAgo = (d: string) => {
    const diff = Date.now() - new Date(d).getTime();
    const mins = Math.floor(diff / 60000);
    if (mins < 60) return `${mins} phút trước`;
    const hrs = Math.floor(mins / 60);
    if (hrs < 24) return `${hrs} giờ trước`;
    const days = Math.floor(hrs / 24);
    return `${days} ngày trước`;
};

/* ─── Mock Data (remove when BE is ready) ─── */
const MOCK_APPOINTMENTS: DoctorAppointment[] = [
    {
        id: "mock-1",
        patientId: "p1",
        doctorId: "d1",
        appointmentDate: "2026-02-25",
        appointmentTime: "09:00",
        appointmentStatus: "PENDING",
        note: "Bệnh nhân bị ngứa da vùng cánh tay trái kéo dài 2 tuần, đã dùng kem bôi nhưng không đỡ.",
        price: 250000,
        paymentStatus: "PENDING",
        created_at: new Date(Date.now() - 2 * 60 * 60 * 1000).toISOString(),
        updated_at: new Date().toISOString(),
        patient: { id: "p1", fullName: "Nguyễn Văn An", email: "an.nguyen@gmail.com", phone: "0901234567", gender: "MALE" },
    },
    {
        id: "mock-2",
        patientId: "p2",
        doctorId: "d1",
        appointmentDate: "2026-02-26",
        appointmentTime: "14:30",
        appointmentStatus: "CONFIRMED",
        note: "Tái khám sau điều trị mụn trứng cá.",
        price: 300000,
        paymentStatus: "PAID",
        created_at: new Date(Date.now() - 24 * 60 * 60 * 1000).toISOString(),
        updated_at: new Date().toISOString(),
        patient: { id: "p2", fullName: "Trần Thị Bích", email: "bich.tran@gmail.com", phone: "0912345678", gender: "FEMALE" },
    },
    {
        id: "mock-3",
        patientId: "p3",
        doctorId: "d1",
        appointmentDate: "2026-02-20",
        appointmentTime: "10:00",
        appointmentStatus: "COMPLETED",
        note: "Khám tổng quát da liễu định kỳ.",
        price: 200000,
        paymentStatus: "PAID",
        created_at: new Date(Date.now() - 3 * 24 * 60 * 60 * 1000).toISOString(),
        updated_at: new Date().toISOString(),
        patient: { id: "p3", fullName: "Lê Hoàng Minh", email: "minh.le@gmail.com", phone: "0923456789", gender: "MALE" },
    },
    {
        id: "mock-4",
        patientId: "p4",
        doctorId: "d1",
        appointmentDate: "2026-02-22",
        appointmentTime: "16:00",
        appointmentStatus: "CANCELLED",
        note: "",
        price: 250000,
        paymentStatus: "CANCELLED",
        created_at: new Date(Date.now() - 5 * 24 * 60 * 60 * 1000).toISOString(),
        updated_at: new Date().toISOString(),
        patient: { id: "p4", fullName: "Phạm Mai Linh", email: "linh.pham@gmail.com", phone: "0934567890", gender: "FEMALE" },
    },
];

/* ─── Component ─── */
export default function DoctorAppointments() {
    const [appointments, setAppointments] = useState<DoctorAppointment[]>([]);
    const [loading, setLoading] = useState(true);
    const [filter, setFilter] = useState("ALL");
    const [updatingId, setUpdatingId] = useState<string | null>(null);
    const [expandedId, setExpandedId] = useState<string | null>(null);
    const [searchTerm, setSearchTerm] = useState("");
    const [editingId, setEditingId] = useState<string | null>(null);
    const [editForm, setEditForm] = useState({ appointmentDate: "", appointmentTime: "", price: 0 });
    const [savingEdit, setSavingEdit] = useState(false);

    useEffect(() => { fetchAppointments(); }, []);

    const fetchAppointments = async () => {
        setLoading(true);
        try {
            const data = await getDoctorAppointments();
            setAppointments(data.length > 0 ? data : MOCK_APPOINTMENTS);
        } catch (err) {
            console.error("Failed to load appointments, using mock data:", err);
            setAppointments(MOCK_APPOINTMENTS);
        } finally {
            setLoading(false);
        }
    };

    const handleUpdateStatus = async (id: string, status: string) => {
        setUpdatingId(id);
        try {
            await updateAppointmentStatus(id, status);
            setAppointments(prev =>
                prev.map(a => a.id === id ? { ...a, appointmentStatus: status } : a)
            );
        } catch (err) {
            console.error("Failed to update:", err);
            alert("Cập nhật trạng thái thất bại!");
        } finally {
            setUpdatingId(null);
        }
    };

    const startEditing = (apt: DoctorAppointment) => {
        setEditingId(apt.id);
        setEditForm({
            appointmentDate: apt.appointmentDate?.split("T")[0] || "",
            appointmentTime: apt.appointmentTime || "",
            price: apt.price || 0,
        });
    };

    const cancelEditing = () => {
        setEditingId(null);
    };

    const saveEdit = async (id: string) => {
        setSavingEdit(true);
        try {
            await updateAppointmentDetails(id, editForm);
            setAppointments(prev =>
                prev.map(a => a.id === id ? { ...a, ...editForm } : a)
            );
            setEditingId(null);
        } catch (err) {
            console.error("Failed to save:", err);
            alert("Lưu thay đổi thất bại!");
        } finally {
            setSavingEdit(false);
        }
    };

    /* ─── Filtered + Searched ─── */
    const filtered = appointments
        .filter(a => filter === "ALL" || a.appointmentStatus === filter)
        .filter(a => {
            if (!searchTerm) return true;
            const q = searchTerm.toLowerCase();
            return (
                a.patient?.fullName?.toLowerCase().includes(q) ||
                a.patient?.email?.toLowerCase().includes(q) ||
                a.patient?.phone?.toLowerCase().includes(q) ||
                a.note?.toLowerCase().includes(q)
            );
        });

    /* ─── Stats ─── */
    const stats = {
        total: appointments.length,
        pending: appointments.filter(a => a.appointmentStatus === "PENDING").length,
        confirmed: appointments.filter(a => a.appointmentStatus === "CONFIRMED").length,
        completed: appointments.filter(a => a.appointmentStatus === "COMPLETED").length,
    };

    /* ─── Loading Skeleton ─── */
    if (loading) {
        return (
            <div className="space-y-4">
                {/* Stats skeleton */}
                <div className="grid grid-cols-2 md:grid-cols-4 gap-3">
                    {[...Array(4)].map((_, i) => (
                        <div key={i} className="rounded-2xl border border-slate-200 bg-white p-4 animate-pulse">
                            <div className="h-3 w-20 bg-slate-200 rounded mb-2" />
                            <div className="h-7 w-12 bg-slate-200 rounded" />
                        </div>
                    ))}
                </div>
                {/* Cards skeleton */}
                <div className="space-y-3">
                    {[...Array(3)].map((_, i) => (
                        <div key={i} className="rounded-2xl border border-slate-200 bg-white p-5 animate-pulse">
                            <div className="flex gap-4">
                                <div className="h-12 w-12 rounded-full bg-slate-200" />
                                <div className="flex-1 space-y-2">
                                    <div className="h-4 w-40 bg-slate-200 rounded" />
                                    <div className="h-3 w-64 bg-slate-200 rounded" />
                                    <div className="h-3 w-32 bg-slate-200 rounded" />
                                </div>
                            </div>
                        </div>
                    ))}
                </div>
            </div>
        );
    }

    return (
        <div className="space-y-5">
            {/* ═══ Stats Cards ═══ */}
            <div className="grid grid-cols-2 md:grid-cols-4 gap-3">
                <StatCard label="Tổng lịch hẹn" value={stats.total} icon="📊" color="slate" />
                <StatCard label="Chờ xác nhận" value={stats.pending} icon="⏳" color="amber" />
                <StatCard label="Đã xác nhận" value={stats.confirmed} icon="✅" color="blue" />
                <StatCard label="Hoàn thành" value={stats.completed} icon="🎉" color="green" />
            </div>

            {/* ═══ Toolbar: Search + Filter ═══ */}
            <div className="rounded-2xl border border-slate-200 bg-white p-4 shadow-soft">
                {/* Search */}
                <div className="relative mb-3">
                    <svg className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-slate-400" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" />
                    </svg>
                    <input
                        type="text"
                        placeholder="Tìm theo tên, email, SĐT bệnh nhân..."
                        value={searchTerm}
                        onChange={e => setSearchTerm(e.target.value)}
                        className="w-full rounded-xl border border-slate-200 bg-slate-50 py-2.5 pl-10 pr-4 text-sm text-slate-700 placeholder:text-slate-400 focus:border-dermcare focus:bg-white focus:outline-none focus:ring-2 focus:ring-dermcare/20 transition"
                    />
                </div>

                {/* Filter Tabs */}
                <div className="flex gap-2 flex-wrap">
                    {FILTER_TABS.map(tab => {
                        const count = tab.value === "ALL"
                            ? appointments.length
                            : appointments.filter(a => a.appointmentStatus === tab.value).length;
                        return (
                            <button
                                key={tab.value}
                                onClick={() => setFilter(tab.value)}
                                className={`inline-flex items-center gap-1.5 rounded-full px-3.5 py-1.5 text-xs font-medium transition-all ${filter === tab.value
                                    ? "bg-dermcare text-white shadow-md shadow-dermcare/25 scale-105"
                                    : "bg-slate-100 text-slate-600 hover:bg-slate-200"
                                    }`}
                            >
                                <span>{tab.icon}</span>
                                <span>{tab.label}</span>
                                <span className={`ml-0.5 inline-flex h-5 w-5 items-center justify-center rounded-full text-[10px] font-bold ${filter === tab.value ? "bg-white/25 text-white" : "bg-slate-200/80 text-slate-500"
                                    }`}>
                                    {count}
                                </span>
                            </button>
                        );
                    })}
                </div>
            </div>

            {/* ═══ Appointment Cards ═══ */}
            {filtered.length === 0 ? (
                <div className="rounded-2xl border border-dashed border-slate-300 bg-white py-16 text-center">
                    <p className="text-5xl mb-3">📭</p>
                    <p className="text-base font-semibold text-slate-700">Không có lịch hẹn nào</p>
                    <p className="text-sm text-slate-400 mt-1">
                        {searchTerm
                            ? `Không tìm thấy kết quả cho "${searchTerm}"`
                            : filter !== "ALL"
                                ? `Không có lịch hẹn "${FILTER_TABS.find(t => t.value === filter)?.label}"`
                                : "Chưa có bệnh nhân nào đặt lịch"}
                    </p>
                </div>
            ) : (
                <div className="space-y-3">
                    {filtered.map(apt => {
                        const status = APPOINTMENT_STATUS[apt.appointmentStatus] || APPOINTMENT_STATUS.PENDING;
                        const payment = PAYMENT_STATUS[apt.paymentStatus] || PAYMENT_STATUS.PENDING;
                        const isExpanded = expandedId === apt.id;
                        const isUpdating = updatingId === apt.id;

                        return (
                            <div
                                key={apt.id}
                                className={`group rounded-2xl border bg-white shadow-soft transition-all hover:shadow-md ${status.border}`}
                            >
                                {/* ─ Main Row ─ */}
                                <div
                                    className="flex flex-col sm:flex-row sm:items-center gap-4 p-5 cursor-pointer"
                                    onClick={() => setExpandedId(isExpanded ? null : apt.id)}
                                >
                                    {/* Avatar */}
                                    <div className={`flex-shrink-0 h-12 w-12 rounded-full ${status.bg} ${status.border} border flex items-center justify-center text-lg font-bold ${status.text}`}>
                                        {apt.patient?.fullName?.charAt(0)?.toUpperCase() || "?"}
                                    </div>

                                    {/* Info */}
                                    <div className="flex-1 min-w-0">
                                        <div className="flex items-center gap-2 flex-wrap">
                                            <h3 className="text-sm font-bold text-slate-900 truncate">
                                                {apt.patient?.fullName || "Bệnh nhân"}
                                            </h3>
                                            {/* Appointment Status Badge */}
                                            <span className={`inline-flex items-center gap-1 rounded-full px-2.5 py-0.5 text-[11px] font-semibold ${status.text} ${status.bg} ${status.border} border`}>
                                                <span className={`h-1.5 w-1.5 rounded-full ${status.dot}`} />
                                                {status.label}
                                            </span>
                                            {/* Payment Status Badge */}
                                            <span className={`inline-flex items-center gap-1 rounded-full px-2 py-0.5 text-[11px] font-medium ${payment.text} ${payment.bg}`}>
                                                {payment.icon} {payment.label}
                                            </span>
                                        </div>
                                        <div className="flex flex-wrap items-center gap-x-4 gap-y-1 mt-1.5 text-xs text-slate-500">
                                            <span className="inline-flex items-center gap-1">
                                                <svg className="h-3.5 w-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M8 7V3m8 4V3m-9 8h10M5 21h14a2 2 0 002-2V7a2 2 0 00-2-2H5a2 2 0 00-2 2v12a2 2 0 002 2z" /></svg>
                                                {formatDate(apt.appointmentDate)}
                                            </span>
                                            <span className="inline-flex items-center gap-1">
                                                <svg className="h-3.5 w-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>
                                                {apt.appointmentTime}
                                            </span>
                                            <span className="inline-flex items-center gap-1 font-semibold text-dermcare">
                                                {formatCurrency(apt.price)}
                                            </span>
                                        </div>
                                    </div>

                                    {/* Actions + Expand */}
                                    <div className="flex items-center gap-2 flex-shrink-0">
                                        {/* Quick Action Buttons (desktop) */}
                                        <div className="hidden sm:flex gap-2">
                                            {apt.appointmentStatus === "PENDING" && (
                                                <>
                                                    <button
                                                        onClick={e => { e.stopPropagation(); handleUpdateStatus(apt.id, "CONFIRMED"); }}
                                                        disabled={isUpdating}
                                                        className="rounded-lg bg-blue-600 px-3.5 py-1.5 text-xs font-semibold text-white shadow-sm hover:bg-blue-700 hover:shadow-md transition-all disabled:opacity-50 disabled:cursor-not-allowed"
                                                    >
                                                        {isUpdating ? "⏳" : "✓ Xác nhận"}
                                                    </button>
                                                    <button
                                                        onClick={e => { e.stopPropagation(); handleUpdateStatus(apt.id, "CANCELLED"); }}
                                                        disabled={isUpdating}
                                                        className="rounded-lg border border-red-200 bg-red-50 px-3.5 py-1.5 text-xs font-semibold text-red-600 hover:bg-red-100 hover:border-red-300 transition-all disabled:opacity-50 disabled:cursor-not-allowed"
                                                    >
                                                        {isUpdating ? "⏳" : "✗ Từ chối"}
                                                    </button>
                                                </>
                                            )}
                                            {apt.appointmentStatus === "CONFIRMED" && (
                                                <button
                                                    onClick={e => { e.stopPropagation(); handleUpdateStatus(apt.id, "COMPLETED"); }}
                                                    disabled={isUpdating}
                                                    className="rounded-lg bg-green-600 px-3.5 py-1.5 text-xs font-semibold text-white shadow-sm hover:bg-green-700 hover:shadow-md transition-all disabled:opacity-50 disabled:cursor-not-allowed"
                                                >
                                                    {isUpdating ? "⏳" : "✓ Hoàn thành"}
                                                </button>
                                            )}
                                        </div>

                                        {/* Expand Arrow */}
                                        <svg
                                            className={`h-5 w-5 text-slate-400 transition-transform duration-200 ${isExpanded ? "rotate-180" : ""}`}
                                            fill="none" stroke="currentColor" viewBox="0 0 24 24"
                                        >
                                            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 9l-7 7-7-7" />
                                        </svg>
                                    </div>
                                </div>

                                {/* ─ Expanded Details ─ */}
                                {isExpanded && (
                                    <div className="border-t border-slate-100 px-5 pb-5 pt-4 animate-in fade-in slide-in-from-top-2 duration-200">
                                        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                                            {/* Patient Details */}
                                            <div className="rounded-xl bg-slate-50 p-4">
                                                <h4 className="text-xs font-bold text-slate-500 uppercase tracking-wider mb-3">Thông tin bệnh nhân</h4>
                                                <div className="space-y-2">
                                                    <DetailRow label="Họ tên" value={apt.patient?.fullName} />
                                                    <DetailRow label="Email" value={apt.patient?.email} />
                                                    <DetailRow label="SĐT" value={apt.patient?.phone} />
                                                    <DetailRow label="Giới tính" value={
                                                        apt.patient?.gender === "MALE" ? "Nam" :
                                                            apt.patient?.gender === "FEMALE" ? "Nữ" : apt.patient?.gender
                                                    } />
                                                </div>
                                            </div>

                                            {/* Appointment Details */}
                                            <div className="rounded-xl bg-slate-50 p-4">
                                                <div className="flex items-center justify-between mb-3">
                                                    <h4 className="text-xs font-bold text-slate-500 uppercase tracking-wider">Chi tiết lịch hẹn</h4>
                                                    {editingId !== apt.id && (apt.appointmentStatus === "PENDING" || apt.appointmentStatus === "CONFIRMED" || apt.appointmentStatus === "RESCHEDULED") && (
                                                        <button
                                                            onClick={(e) => { e.stopPropagation(); startEditing(apt); }}
                                                            className="inline-flex items-center gap-1 rounded-lg bg-dermcare/10 px-2.5 py-1 text-[11px] font-semibold text-dermcare hover:bg-dermcare/20 transition"
                                                        >
                                                            ✏️ Chỉnh sửa
                                                        </button>
                                                    )}
                                                </div>

                                                {editingId === apt.id ? (
                                                    /* ── Edit Mode ── */
                                                    <div className="space-y-3">
                                                        <div>
                                                            <label className="block text-[11px] font-medium text-slate-500 mb-1">📅 Ngày khám</label>
                                                            <input
                                                                type="date"
                                                                value={editForm.appointmentDate}
                                                                onChange={e => setEditForm({ ...editForm, appointmentDate: e.target.value })}
                                                                className="w-full rounded-lg border border-slate-200 bg-white px-3 py-2 text-sm text-slate-800 focus:border-dermcare focus:outline-none focus:ring-2 focus:ring-dermcare/20 transition"
                                                            />
                                                        </div>
                                                        <div>
                                                            <label className="block text-[11px] font-medium text-slate-500 mb-1">🕐 Giờ khám</label>
                                                            <input
                                                                type="time"
                                                                value={editForm.appointmentTime}
                                                                onChange={e => setEditForm({ ...editForm, appointmentTime: e.target.value })}
                                                                className="w-full rounded-lg border border-slate-200 bg-white px-3 py-2 text-sm text-slate-800 focus:border-dermcare focus:outline-none focus:ring-2 focus:ring-dermcare/20 transition"
                                                            />
                                                        </div>
                                                        <div>
                                                            <label className="block text-[11px] font-medium text-slate-500 mb-1">💰 Giá khám (VND)</label>
                                                            <input
                                                                type="number"
                                                                value={editForm.price}
                                                                onChange={e => setEditForm({ ...editForm, price: Number(e.target.value) })}
                                                                min={0}
                                                                step={10000}
                                                                className="w-full rounded-lg border border-slate-200 bg-white px-3 py-2 text-sm text-slate-800 focus:border-dermcare focus:outline-none focus:ring-2 focus:ring-dermcare/20 transition"
                                                            />
                                                        </div>
                                                        <div className="flex gap-2 pt-1">
                                                            <button
                                                                onClick={() => saveEdit(apt.id)}
                                                                disabled={savingEdit}
                                                                className="flex-1 rounded-lg bg-dermcare px-4 py-2 text-xs font-semibold text-white shadow-sm hover:bg-dermcare-dark transition disabled:opacity-50"
                                                            >
                                                                {savingEdit ? "⏳ Đang lưu..." : "💾 Lưu thay đổi"}
                                                            </button>
                                                            <button
                                                                onClick={cancelEditing}
                                                                disabled={savingEdit}
                                                                className="rounded-lg border border-slate-200 bg-white px-4 py-2 text-xs font-medium text-slate-600 hover:bg-slate-50 transition disabled:opacity-50"
                                                            >
                                                                Hủy
                                                            </button>
                                                        </div>
                                                    </div>
                                                ) : (
                                                    /* ── View Mode ── */
                                                    <div className="space-y-2">
                                                        <DetailRow label="Ngày khám" value={formatDate(apt.appointmentDate)} />
                                                        <DetailRow label="Giờ khám" value={apt.appointmentTime} />
                                                        <DetailRow label="Giá khám" value={formatCurrency(apt.price)} highlight />
                                                        <DetailRow label="Thanh toán" value={`${payment.icon} ${payment.label}`} />
                                                        <DetailRow label="Ngày tạo" value={timeAgo(apt.created_at)} />
                                                    </div>
                                                )}
                                            </div>
                                        </div>

                                        {/* Note */}
                                        {apt.note && (
                                            <div className="mt-4 rounded-xl bg-amber-50 border border-amber-100 p-4">
                                                <h4 className="text-xs font-bold text-amber-700 uppercase tracking-wider mb-1.5">📝 Ghi chú / Triệu chứng</h4>
                                                <p className="text-sm text-amber-900 leading-relaxed">{apt.note}</p>
                                            </div>
                                        )}

                                        {/* Mobile Action Buttons */}
                                        <div className="flex gap-2 mt-4 sm:hidden">
                                            {apt.appointmentStatus === "PENDING" && (
                                                <>
                                                    <button
                                                        onClick={() => handleUpdateStatus(apt.id, "CONFIRMED")}
                                                        disabled={isUpdating}
                                                        className="flex-1 rounded-xl bg-blue-600 py-2.5 text-sm font-semibold text-white shadow-sm hover:bg-blue-700 transition disabled:opacity-50"
                                                    >
                                                        {isUpdating ? "⏳" : "✓ Xác nhận"}
                                                    </button>
                                                    <button
                                                        onClick={() => handleUpdateStatus(apt.id, "CANCELLED")}
                                                        disabled={isUpdating}
                                                        className="flex-1 rounded-xl border border-red-200 bg-red-50 py-2.5 text-sm font-semibold text-red-600 hover:bg-red-100 transition disabled:opacity-50"
                                                    >
                                                        {isUpdating ? "⏳" : "✗ Từ chối"}
                                                    </button>
                                                </>
                                            )}
                                            {apt.appointmentStatus === "CONFIRMED" && (
                                                <button
                                                    onClick={() => handleUpdateStatus(apt.id, "COMPLETED")}
                                                    disabled={isUpdating}
                                                    className="flex-1 rounded-xl bg-green-600 py-2.5 text-sm font-semibold text-white shadow-sm hover:bg-green-700 transition disabled:opacity-50"
                                                >
                                                    {isUpdating ? "⏳" : "✓ Hoàn thành"}
                                                </button>
                                            )}
                                        </div>
                                    </div>
                                )}
                            </div>
                        );
                    })}
                </div>
            )}
        </div>
    );
}

/* ─── Sub-components ─── */
function StatCard({ label, value, icon, color }: { label: string; value: number; icon: string; color: string }) {
    const colorMap: Record<string, string> = {
        slate: "from-slate-50 to-white border-slate-200",
        amber: "from-amber-50 to-white border-amber-200",
        blue: "from-blue-50 to-white border-blue-200",
        green: "from-green-50 to-white border-green-200",
    };
    const textMap: Record<string, string> = {
        slate: "text-slate-900",
        amber: "text-amber-600",
        blue: "text-blue-600",
        green: "text-green-600",
    };
    return (
        <div className={`rounded-2xl border bg-gradient-to-br ${colorMap[color]} p-4 shadow-soft transition hover:shadow-md`}>
            <div className="flex items-center justify-between mb-1">
                <span className="text-xs font-medium text-slate-500">{label}</span>
                <span className="text-lg">{icon}</span>
            </div>
            <p className={`text-2xl font-bold ${textMap[color]}`}>{value}</p>
        </div>
    );
}

function DetailRow({ label, value, highlight }: { label: string; value?: string | null; highlight?: boolean }) {
    return (
        <div className="flex items-center justify-between">
            <span className="text-xs text-slate-500">{label}</span>
            <span className={`text-sm font-medium ${highlight ? "text-dermcare font-bold" : "text-slate-800"}`}>
                {value || <span className="text-slate-300 italic">—</span>}
            </span>
        </div>
    );
}
